-- 2026-10-02: phone and employee ID per person, kept in the Staff & Org Chart tab by the Fleet Admin team (HQ staff and above can read them).
-- Backfilled for the Station Heads / Fleet Assistants from the MY - Fleet Management sheet ('SH & FA Manpower'); "TBA" cells are left empty,
-- and a value somebody already typed in is never overwritten.
ALTER TABLE users
    ADD COLUMN phone VARCHAR(30) NULL AFTER display_name,
    ADD COLUMN employee_id VARCHAR(30) NULL AFTER phone;

